import sys
import re

def is_valid_jabber_id(jid):
    parts = jid.split('@')
    if len(parts) != 2:
        return 'NO'
    username, rest = parts
    if not (1 <= len(username) <= 16) or not re.match(r'^[a-zA-Z0-9_]+$', username):
        return 'NO'
    if '/' in rest:
        hostname, resource = rest.split('/', 1)
    else:
        hostname, resource = rest, ''
    if not (1 <= len(hostname) <= 32) or not all(1 <= len(word) <= 16 and re.match(r'^[a-zA-Z0-9_]+$', word) for word in hostname.split('.')):
        return 'NO'
    if resource and not (1 <= len(resource) <= 16) or not re.match(r'^[a-zA-Za-z0-9_]+$', resource):
        return 'NO'
    return 'YES'

input = sys.stdin.read().strip()
print(is_valid_jabber_id(input))
